import os, json, glob, re, time
from collections import Counter, defaultdict

base = os.path.expanduser("~/.claude/projects")
files = []
for p in glob.glob(os.path.join(base, "*", "*.jsonl")):
    try: files.append((os.path.getmtime(p), p))
    except OSError: pass
files.sort(reverse=True)
files = files[:50]
if not files:
    print("no transcripts"); raise SystemExit

mtimes = [f[0] for f in files]
print(f"WINDOW: {len(files)} sessions, {(max(mtimes)-min(mtimes))/86400:.1f} days")
print("oldest:", time.strftime("%Y-%m-%d", time.localtime(min(mtimes))), " newest:", time.strftime("%Y-%m-%d", time.localtime(max(mtimes))))
print("projects covered:", len(set(os.path.dirname(f[1]) for f in files)))
print()

skill_hits=Counter(); mcp_hits=Counter(); cmd_hits=Counter()
hook_dur=defaultdict(list); hook_timeouts=Counter()
denials=Counter(); denial_kinds=defaultdict(Counter)
tooluse_by_id={}
denied_ids=[]
agent_hits=Counter()

for _,p in files:
    try: lines=open(p,encoding="utf-8",errors="replace").read().splitlines()
    except OSError: continue
    for ln in lines:
        if not ln.strip(): continue
        try: o=json.loads(ln)
        except Exception: continue
        t=o.get("type")
        if t=="assistant":
            for c in (o.get("message",{}) or {}).get("content",[]) or []:
                if isinstance(c,dict) and c.get("type")=="tool_use":
                    n=c.get("name","")
                    tooluse_by_id[c.get("id")]=(n,c.get("input",{}))
                    if n=="Skill":
                        s=(c.get("input") or {}).get("skill")
                        if s: skill_hits[s]+=1
                    elif n.startswith("mcp__"):
                        mcp_hits[n]+=1
                    elif n=="Agent":
                        a=(c.get("input") or {}).get("subagent_type")
                        if a: agent_hits[a]+=1
        elif t=="user":
            dk=o.get("toolDenialKind")
            cont=(o.get("message",{}) or {}).get("content")
            if isinstance(cont,list):
                for c in cont:
                    if isinstance(c,dict) and c.get("type")=="tool_result":
                        if dk and dk not in ("interrupted","cancelled"):
                            denied_ids.append((c.get("tool_use_id"),dk))
            if isinstance(cont,str):
                for m in re.findall(r"<command-name>/?([\w:.-]+)</command-name>", cont):
                    cmd_hits[m]+=1
        elif t=="attachment":
            a=o.get("attachment",{}) or {}
            if str(a.get("type","")).startswith("hook_"):
                key=(a.get("hookName") or a.get("command","?"), a.get("hookEvent","?"))
                d=a.get("durationMs")
                if isinstance(d,(int,float)): hook_dur[key].append(d)
                if a.get("type")=="hook_cancelled" and a.get("timedOut"): hook_timeouts[key]+=1

for tid,dk in denied_ids:
    nm,inp=tooluse_by_id.get(tid,(None,None))
    if not nm: continue
    if nm=="Bash":
        cmdstr=(inp or {}).get("command","")
        toks=cmdstr.strip().split()
        key="Bash: "+" ".join(toks[:2]) if toks else "Bash: ?"
    else:
        key=nm
    denials[key]+=1; denial_kinds[key][dk]+=1

print("=== SKILL invocations (Skill tool) ===")
for k,v in skill_hits.most_common(40): print(f"  {v:4d}  {k}")
print("\n=== slash commands ===")
for k,v in cmd_hits.most_common(30): print(f"  {v:4d}  /{k}")
print("\n=== MCP tool calls by server ===")
srv=Counter()
for k,v in mcp_hits.items():
    m=re.match(r"mcp__([^_].*?)__", k)
    srv[m.group(1) if m else k]+=v
for k,v in srv.most_common(30): print(f"  {v:5d}  {k}")
print("\n=== subagent types ===")
for k,v in agent_hits.most_common(15): print(f"  {v:4d}  {k}")
print("\n=== HOOK timings (count / median / max ms) ===")
for k,v in sorted(hook_dur.items(), key=lambda x:-max(x[1])):
    v2=sorted(v); med=v2[len(v2)//2]
    print(f"  n={len(v):4d} med={med:7.0f} max={max(v):8.0f}  {str(k)[:120]}")
print("timeouts:", dict(hook_timeouts) if hook_timeouts else "none")
print("\n=== DENIALS (top 25) ===")
for k,v in denials.most_common(25):
    print(f"  {v:4d}  {k}   kinds={dict(denial_kinds[k])}")
